import { initialLists, CURRENT_USER_ID, allUsers } from "../data/mockData";

const USE_MOCK_API = true;
const MOCK_DELAY = 800;

let mockDatabase = JSON.parse(JSON.stringify(initialLists));

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export const api = {
  // 1. getLists
  getLists: async () => {
    if (USE_MOCK_API) {
      await sleep(MOCK_DELAY);
      return mockDatabase.filter(list => list.members.includes(CURRENT_USER_ID));
    } else {
      const response = await fetch("/shoppingList/list");
      if (!response.ok) throw new Error("Network response was not ok");
      return response.json();
    }
  },

  // 2. getListDetail
  getListDetail: async (listId) => {
    if (USE_MOCK_API) {
      await sleep(MOCK_DELAY);
      const list = mockDatabase.find((l) => l.id === listId);
      
      if (!list) throw new Error("Seznam nebyl nalezen (404).");
      if (!list.members.includes(CURRENT_USER_ID)) throw new Error("Nemáte přístup k tomuto seznamu (403).");
      
      return { ...list };
    } else {
      const response = await fetch(`/shoppingList/get?id=${listId}`);
      if (!response.ok) throw new Error("Failed to fetch list");
      return response.json();
    }
  },

  // 3. createList
  createList: async (name) => {
    if (USE_MOCK_API) {
      await sleep(MOCK_DELAY);
      const newList = {
        id: `list-${Date.now()}`,
        name: name,
        owner: CURRENT_USER_ID,
        members: [CURRENT_USER_ID],
        archived: false,
        items: [],
      };
      mockDatabase.push(newList);
      return newList;
    } else {
      const response = await fetch("/shoppingList/create", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name }),
      });
      if (!response.ok) throw new Error("Failed to create list");
      return response.json();
    }
  },

  // 4. updateListName
  updateListName: async (listId, newName) => {
    if (USE_MOCK_API) {
      await sleep(MOCK_DELAY);
      const list = mockDatabase.find((l) => l.id === listId);
      if (list) list.name = newName;
      return list;
    } else {
      /* Real fetch implementation */
    }
  },

  // 5. toggleArchiveList
  toggleArchiveList: async (listId) => {
    if (USE_MOCK_API) {
      await sleep(MOCK_DELAY / 2);
      const list = mockDatabase.find((l) => l.id === listId);
      if (list) list.archived = !list.archived;
      return list;
    } else {
      /* Real fetch implementation */
    }
  },

  // 6. deleteList
  deleteList: async (listId) => {
    if (USE_MOCK_API) {
      await sleep(MOCK_DELAY);
      mockDatabase = mockDatabase.filter((l) => l.id !== listId);
      return { success: true };
    } else {
      /* Real fetch implementation */
    }
  },

  // 7. addItem
  addItem: async (listId, itemName) => {
    if (USE_MOCK_API) {
      await sleep(MOCK_DELAY / 2);
      const list = mockDatabase.find((l) => l.id === listId);
      if (list) {
        const newItem = {
          id: `item-${Date.now()}`,
          name: itemName,
          solved: false,
        };
        list.items.push(newItem);
        return newItem;
      }
    } else {
      /* Real fetch implementation */
    }
  },

  // 8. toggleItemSolved
  toggleItemSolved: async (listId, itemId) => {
    if (USE_MOCK_API) {
      await sleep(200);
      const list = mockDatabase.find((l) => l.id === listId);
      if (list) {
        const item = list.items.find(i => i.id === itemId);
        if (item) item.solved = true;
      }
      return { success: true };
    } else { /* ... */ }
  },

  // 9. deleteItem
  deleteItem: async (listId, itemId) => {
    if (USE_MOCK_API) {
      await sleep(200);
      const list = mockDatabase.find((l) => l.id === listId);
      if (list) {
        list.items = list.items.filter(i => i.id !== itemId);
      }
      return { success: true };
    } else { /* ... */ }
  },

  // 10. manageMember
  manageMember: async (listId, memberId, action) => {
    if (USE_MOCK_API) {
      await sleep(MOCK_DELAY);
      const list = mockDatabase.find(l => l.id === listId);
      if(list) {
        if(action === 'add' && !list.members.includes(memberId)) {
           list.members.push(memberId);
        } else if (action === 'remove') {
           list.members = list.members.filter(id => id !== memberId);
        }
      }
      return list;
    } else { /* ... */ }
  },
  
  // 11. getAllUsers
  getAllUsers: async () => {
      await sleep(200);
      return allUsers;
  }
};
